/**
 * shape Content = Post or Photo {
 *     commentCount: integer = count(comments)
 * }
 *
 * shape Popular = Content where count(comments) >= 2
 *
 * rule NotePopularity when Popular {
 *     PopularityNotice from { content: this, noticedOn: now }
 * }
 *
 */
class ContentSpec : SpecSupport() {

    @Test
    fun `NotePopularity - a new Popular produces a PopularityNotice`() {
        val beforePopularityNotice = count("PopularityNotice")
        // given: one new subject entered 'Popular'
        val content = givens.popular()
        content.assertIsA("Popular", "the given must deliver a member of 'Popular'")
        assertEquals(beforePopularityNotice + 1, count("PopularityNotice"), "rule NotePopularity: one 'PopularityNotice' per firing")
        val producedPopularityNotice = last("PopularityNotice")
        assertEquals(content.id, field(producedPopularityNotice, "content"), "PopularityNotice.content: this")
